$('weapon-toggle').onclick=()=>{if(mode!=='play'||blocked())return;combat.weapon=combat.weapon==='pm'?'crowbar':'pm';combat.reloading=0;resetInput();persist();updateHUD();};
function restartCombat(){resetInput();combat=createCombat();state.health=83;state.x=state.location==='garages'?840:923;state.y=state.location==='garages'?820:724;state.inside=false;state.room=null;downedShown=false;closeAll();persist();updateHUD();}
$('retry-combat').onclick=restartCombat;$('reset-combat').onclick=restartCombat;
